mapper.select:
SELECT assessment_hash
  FROM readiness_assessment
 WHERE tenant_id = #{tenantId}
   AND program_id = #{programId}
   AND environment = #{environment}
   AND assessment_id = #{assessmentId}

SELECT assessment_id, format_version, level, status, evaluated_at, accepted_evidence_json,
       blockers_json, assessment_hash
  FROM readiness_assessment
 WHERE tenant_id = #{tenantId}
   AND program_id = #{programId}
   AND environment = #{environment}
   AND level = #{level}
 ORDER BY committed_revision DESC, assessment_id ASC
